import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import 'api.dart';
import 'local_store.dart';

const gold=Color(0xFFD6AE55),black=Color(0xFF101010),panel=Color(0xFF202020);
const modules=['sales','purchase','bills','customers','suppliers','stock','accounts','reports','karigar','repairs','ledger','expenses','staff','orders'];
String label(String s)=>s[0].toUpperCase()+s.substring(1).replaceAll('_',' ');
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await Api.init();await LocalStore.db;runApp(const App());}
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'Gold & Silver',debugShowCheckedModeBanner:false,theme:ThemeData(brightness:Brightness.dark,scaffoldBackgroundColor:black,colorScheme:const ColorScheme.dark(primary:gold,surface:panel),useMaterial3:true),home:Api.token==null?const Login():const Home());}
class Login extends StatefulWidget{const Login({super.key});@override State<Login>createState()=>_LoginState();}
class _LoginState extends State<Login>{final email=TextEditingController(),pass=TextEditingController(),url=TextEditingController(text:Api.base);bool busy=false;String error='';
 Future<void>go()async{setState(()=>busy=true);try{await Api.configure(url.text);await Api.login(email.text.trim(),pass.text);if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Home()));}catch(e){setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext c)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:Column(children:[const Icon(Icons.diamond,color:gold,size:64),const Text('GOLD & SILVER',style:TextStyle(color:gold,fontSize:25,fontWeight:FontWeight.bold)),const SizedBox(height:22),TextField(controller:url,decoration:const InputDecoration(labelText:'API Server URL')),TextField(controller:email,decoration:const InputDecoration(labelText:'Email')),TextField(controller:pass,obscureText:true,decoration:const InputDecoration(labelText:'Password')),if(error.isNotEmpty)Text(error,style:const TextStyle(color:Colors.redAccent)),const SizedBox(height:16),FilledButton(onPressed:busy?null:go,child:Text(busy?'Connecting...':'Login'))]))));}
}
class Home extends StatefulWidget{const Home({super.key});@override State<Home>createState()=>_HomeState();}
class _HomeState extends State<Home>{List<dynamic> shops=[];int? shop;Map<String,dynamic> summary={};String err='';
 Future<void>load()async{try{final s=await Api.request('GET','/shops');setState((){shops=List<dynamic>.from(s); if(shops.isNotEmpty)shop??=shops.first['id'];});if(shop!=null){final x=await Api.request('GET','/shops/$shop/summary');setState(()=>summary=x);}}catch(e){setState(()=>err=e.toString());}}
 @override void initState(){super.initState();load();}
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('GOLD & SILVER'),actions:[IconButton(onPressed:()async{if(shop!=null){final n=await Api.syncPending(shop!);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$n pending changes synced')));await load();}},icon:const Icon(Icons.sync)),IconButton(onPressed:()async{await Api.logout();if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Login()));},icon:const Icon(Icons.logout))]),body:shops.isEmpty?Center(child:Text(err.isEmpty?'Loading shops...':err)):ListView(padding:const EdgeInsets.all(14),children:[
 const Text('JEWELLERY BUSINESS MANAGER',style:TextStyle(color:gold,letterSpacing:1.5)),const SizedBox(height:12),
 DropdownButtonFormField<int>(value:shop,items:shops.map((s)=>DropdownMenuItem<int>(value:s['id'],child:Text(s['name']))).toList(),onChanged:(v)=>setState((){shop=v;load();}),decoration:const InputDecoration(labelText:'Active shop')),
 const SizedBox(height:12),Wrap(spacing:8,runSpacing:8,children:summary.entries.map((e)=>Chip(label:Text('${label(e.key)}: ${e.value['count']} records'))).toList()),
 GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,childAspectRatio:1.8,children:modules.map((m)=>Card(child:InkWell(onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>Records(shopId:shop!,module:m))),child:Center(child:Text(label(m),style:const TextStyle(color:gold,fontWeight:FontWeight.bold)))))).toList()),
 ]));}
}
class Records extends StatefulWidget{final int shopId;final String module;const Records({super.key,required this.shopId,required this.module});@override State<Records>createState()=>_RecordsState();}
class _RecordsState extends State<Records>{List<Map<String,dynamic>> rows=[];String error='';
 Future<void>load()async{try{final x=await Api.request('GET','/shops/${widget.shopId}/records?module=${widget.module}');rows=List<Map<String,dynamic>>.from(x);for(final r in rows){await LocalStore.cache(r,widget.shopId);}setState((){});}catch(e){rows=await LocalStore.records(widget.shopId,widget.module);setState(()=>error='Offline mode: showing cached records.');}}
 Future<void>add()async{final title=TextEditingController(),party=TextEditingController(),weight=TextEditingController(),rate=TextEditingController(),amount=TextEditingController(),paid=TextEditingController(),notes=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text('New ${label(widget.module)}'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[for(final x in {'Bill / Item':title,'Customer / Supplier':party,'Weight (grams)':weight,'Rate per Tola':rate,'Amount':amount,'Paid':paid,'Notes':notes}.entries)TextField(controller:x.value,decoration:InputDecoration(labelText:x.key),keyboardType:['Weight (grams)','Rate per Tola','Amount','Paid'].contains(x.key)?const TextInputType.numberWithOptions(decimal:true):TextInputType.text)])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(ok!=true)return;
 final a=double.tryParse(amount.text)??0,p=double.tryParse(paid.text)??0;final id=const Uuid().v4();final payload={'id':id,'module':widget.module,'title':title.text,'party':party.text,'details':notes.text,'metal':'Gold','weight':double.tryParse(weight.text)??0,'purity':24,'rate':double.tryParse(rate.text)??0,'making':0,'discount':0,'amount':a,'paid':p,'balance':(a-p).clamp(0,double.infinity),'status':p>=a?'Paid':p>0?'Partial':'Pending','reference':'','version':1};
 try{final r=await Api.request('PUT','/shops/${widget.shopId}/records',body:payload);await LocalStore.cache(r,widget.shopId);}catch(e){await LocalStore.queue(id,'upsert',payload);await LocalStore.cache(payload,widget.shopId);setState(()=>error='Saved locally; pending cloud sync.');}
 await load();}
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(label(widget.module))),floatingActionButton:FloatingActionButton(backgroundColor:gold,foregroundColor:black,onPressed:add,child:const Icon(Icons.add)),body:Column(children:[if(error.isNotEmpty)Padding(padding:const EdgeInsets.all(8),child:Text(error,style:const TextStyle(color:gold))),Expanded(child:rows.isEmpty?const Center(child:Text('No records')):ListView.builder(itemCount:rows.length,itemBuilder:(c,i){final r=rows[i];return Card(child:ListTile(title:Text('${r['title']}'),subtitle:Text('${r['party']} • ${r['weight']}g\nAmount: ${r['amount']} | Paid: ${r['paid']} | Due: ${r['balance']}')));}))]),);
}
